parameters.jsCode:
// Gate A: the channel has to be healthy BEFORE fetching patients and, above all,
// before writing the first key (INV-8). Creating keys and then finding out that
// nothing can be sent BURNS patients: they are marked as handled without having
// received anything. It happened on 2026-07-29/30 with dozens of keys.
const cfg       = $('Config').first().json;
const numbers   = $('Gate A · Number').first().json.items ?? [];
const templates = $('Gate A · Templates').first().json.items ?? [];

const REQUIRED = [
  'followup_20_days_opt1',
  'followup_20_days_opt2',
  'followup_42_days_opt1',
];

const reasons = [];
const number = numbers[0];

if (!number) {
  reasons.push('YCloud returned no phone number');
} else {
  if (number.status !== 'CONNECTED') reasons.push(`The number is ${number.status}, not CONNECTED`);
  if (number.qualityRating === 'RED') reasons.push('The number quality rating is RED');
}

for (const name of REQUIRED) {
  const t = templates.find(p => p.name === name);
  if (!t) reasons.push(`Template ${name} is missing`);
  else if (t.status !== 'APPROVED') reasons.push(`Template ${name} is ${t.status}, not APPROVED`);
}

// A flag that NOBODY writes today (design O-R5). The read stays wired so that the
// only missing piece is the writer, not a gap nobody remembers.
if (String(cfg.account_restricted) === 'true') {
  reasons.push('The account is flagged as restricted in bot.config');
}

// 'TIER_250' -> 250. It is the real ceiling of business-initiated conversations per 24 h.
const limit = Number(String(number?.messagingLimit ?? '').replace(/\D/g, '')) || null;

return [{ json: {
  ok: reasons.length === 0,
  reasons,
  messagingLimit: limit,
  businessNumber: number?.phoneNumber ?? null,
}}];

