parameters.jsCode:
// Decides who is due today. IT WRITES NOTHING: it can be run and its result
// inspected without a single key existing. That property is what makes this
// layer auditable, and it is the only chance to review before INV-1 blocks a
// patient forever.
const CUTOFF_DATE      = '2026-08-01';   // spec 4.1
const SATELLITE_BRANCH = 'SATELLITE';    // spec 4.3: fully excluded
const MAIN_BRANCH      = 'MAIN';         // spec 4.1 and D15: the only one that receives. Exact match, on purpose
const MILESTONES = [
  { name: '20', from: 20, to: 22 },
  { name: '42', from: 42, to: 44 },
];

const pages    = $input.all();
const patients = pages.flatMap(p => p.json.data ?? []);
const declaredTotal = Number(pages[0]?.json?.total ?? 0);

// INV-10 applied to the patient read: an empty list is NOT "nobody today",
// it is a read that failed without raising an error.
if (patients.length === 0) {
  throw new Error('The API returned 0 patients. Aborted: an empty read is not "no candidates".');
}
// And a truncated read is indistinguishable from a slow day. The old graph asked
// for a single page of 500 and lost patient 501 onwards, without anything failing.
if (declaredTotal && patients.length !== declaredTotal) {
  throw new Error(`Truncated read: the API declares ${declaredTotal} patients and ${patients.length} arrived. Aborted.`);
}

const today  = DateTime.now().setZone('America/Costa_Rica').startOf('day');
const cutoff = DateTime.fromISO(CUTOFF_DATE, { zone: 'America/Costa_Rica' }).startOf('day');
const isSunday = today.weekday === 7;

const emitted    = new Set();   // INV-6: dedup within the run
const candidates = [];
const discards   = { no_date: 0, invalid_date: 0, no_phone: 0, odd_phone: 0, satellite: 0,
                     no_branch: 0, other_branch: 0 };
const details    = [];
let active       = 0;
let withMain     = 0;

for (const p of patients) {
  if (p.role !== 'member' || p.status !== 'active') continue;  // not eligible, not a discard
  active++;

  // Branch BEFORE the date (design S-B). The order matters: SATELLITE excludes even if
  // the patient also has MAIN.
  const branches = (Array.isArray(p.branches) ? p.branches : [p.branches])
    .map(s => String(s ?? '').trim())
    .filter(Boolean);
  if (branches.length === 0) { discards.no_branch++; continue; }   // missing data (INV-12)

  const hasMain = branches.includes(MAIN_BRANCH);
  if (hasMain) withMain++;   // for the guard below: counted before removing SATELLITE

  const isSatellite = Array.isArray(p.branches)
    ? p.branches.includes(SATELLITE_BRANCH)
    : String(p.branches ?? '').includes(SATELLITE_BRANCH);
  if (isSatellite) { discards.satellite++; continue; }

  if (!hasMain) { discards.other_branch++; continue; }     // a decision, not data to fix

  if (!p.lastActivePlanStartDate) { discards.no_date++; continue; }

  const m = String(p.lastActivePlanStartDate).match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) {                                     // INV-7: a date is never guessed
    discards.invalid_date++;
    details.push(`${p.id} ${p.name}: odd date "${p.lastActivePlanStartDate}"`);
    continue;
  }
  const planDate = m[0];

  const start = DateTime.fromISO(planDate, { zone: 'America/Costa_Rica' }).startOf('day');
  if (start < cutoff) continue;

  const days = Math.round(today.diff(start, 'days').days);
  if (!MILESTONES.some(h => days >= h.from && days <= h.to)) continue;   // not due today

  // The phone is validated AFTER knowing the patient is due today: that way the
  // discard count (INV-12) measures what was really lost, not background noise.
  if (!p.phone) {
    discards.no_phone++;
    details.push(`${p.id} ${p.name}: NO PHONE and was due today`);
    continue;
  }
  // The data carries invisible text-direction marks (U+202A/U+202C) wrapping the
  // number. The non-digit replace removes them.
  const d = String(p.phone).replace(/\D/g, '');
  let phone = null;
  if (d.length === 8) phone = `+506${d}`;                       // local number without country code
  else if (d.length === 11 && d.startsWith('506')) phone = `+${d}`;
  else if (d.length >= 10 && d.length <= 15) phone = `+${d}`;   // another country, already with its code
  if (!phone) {
    discards.odd_phone++;
    details.push(`${p.id} ${p.name}: phone "${p.phone}" does not fit E.164`);
    continue;
  }

  const fullName = String(p.name ?? '').trim().replace(/\s+/g, ' ');
  const parts = fullName.split(' ');

  for (const milestone of MILESTONES) {
    if (days < milestone.from || days > milestone.to) continue;
    const key = `${p.id}_${planDate}_${milestone.name}`;
    if (emitted.has(key)) continue;          // INV-6
    emitted.add(key);
    candidates.push({
      unique_key:  key,
      patient_id:  String(p.id),
      last_name:   parts.slice(1).join(' '),
      first_name:  parts[0] ?? '',
      full_name:   fullName,
      phone,
      milestone:   milestone.name,
      plan_date:   planDate,
      days,
    });
  }
}

// INV-10 by another road (D15): if nobody has the MAIN branch, the most likely cause
// is that the value changed in the app, not that there are no patients today. Without
// this, the bot would send zero messages every day without a single error.
if (active > 0 && withMain === 0) {
  throw new Error(`No active patient has the branch "${MAIN_BRANCH}" ` +
    `(${active} active: ${discards.no_branch} without branch, ${discards.satellite} SATELLITE, ` +
    `${discards.other_branch} from another branch). Aborted: a filter that leaves everyone out is not "nobody today".`);
}

// A single "envelope" with everything inside. That way no node below runs N times,
// and the summary exists even when there is not a single candidate today (INV-13).
return [{ json: {
  isSunday,
  totalPatients: patients.length,
  discards,
  discardDetails: details.slice(0, 25),
  candidates: isSunday ? [] : candidates,
}}];

const base = $('Compute Candidates').first().json;

const alreadyContacted = new Set(
  $('Existing Keys').all().map(i => i.json.unique_key).filter(Boolean)
);
// REMOVED ON 2026-09-07: there was a guard here that aborted if bot.sends had
// rows and this filter returned zero. It is a FALSE POSITIVE and it fired on the
// first real run.
//
// The filter queries ONLY the keys of today's candidates, so zero is the normal,
// correct result as long as those patients have not been contacted before. The
// guard came from the old Airtable design, where the WHOLE history was read:
// there, a zero with a full table really was suspicious.
//
// The guard that DOES belong already exists, in Gate B: the watermark
// (count(*) < sends_max_seen). It covers the same thing —wrong database, shrunken
// table— plus restoring an old backup (INV-17), and without the false
// positive. It is exactly what design D-E chose so as not to depend on
// "the table is empty". See design O-A.

const last = new Map(
  $('Last Templates').all()
    .filter(i => i.json.patient_id)
    .map(i => [String(i.json.patient_id), i.json.template])
);

const optedOut = new Set(
  $('Marketing Opt-outs').all()
    .flatMap(i => i.json.items ?? [])
    .map(u => String(u.customer ?? '').replace(/\D/g, ''))
    .filter(Boolean)
);

const chosen = [];
let alreadyContactedCount = 0;
let optOutsApplied = 0;

for (const c of base.candidates) {
  if (alreadyContacted.has(c.unique_key)) { alreadyContactedCount++; continue; }

  let template, params, category;

  if (c.milestone === '42') {
    template = 'followup_42_days_opt1';
    category = 'utility';
    // {{2}} is the appointment date IN SPANISH AND HUMAN-READABLE: "4 de Setiembre".
    // Sending the ISO date raises no error: it sends an ugly message to a real patient.
    const f = DateTime.fromISO(c.plan_date, { zone: 'America/Costa_Rica' }).setLocale('es');
    const month = f.toFormat('MMMM');
    params = [c.first_name, `${f.day} de ${month.charAt(0).toUpperCase()}${month.slice(1)}`];
  } else {
    // Alternation (spec 4.6): if the last one was opt1, opt2 is due; if it was opt2 or
    // there is none, opt1.
    const previous = last.get(c.patient_id);
    template = previous === 'followup_20_days_opt1'
      ? 'followup_20_days_opt2'
      : 'followup_20_days_opt1';

    // opt2 is Marketing. If the patient opted out, they get opt1 (Utility).
    if (template === 'followup_20_days_opt2' && optedOut.has(c.phone.replace(/\D/g, ''))) {
      template = 'followup_20_days_opt1';
      optOutsApplied++;
    }
    category = template.endsWith('opt2') ? 'marketing' : 'utility';
    params = [c.first_name];
  }

  chosen.push({ ...c, template, category, params });
}

return [{ json: { ...base, candidates: chosen, alreadyContacted: alreadyContactedCount, optOutsApplied } }];

// Gate B: the four checks that need to know HOW MANY candidates there are.
// Counting writes nothing, so evaluating them here still honours INV-8:
// "before writing the first key".
const base  = $('Pick Template').first().json;
const cfg   = $('Config').first().json;
const gateA = $('Evaluate Gate A').first().json;

const n = base.candidates.length;
const reasons = [];

// 1. Anomaly brake (spec 4.4). Abort and shout, never truncate and stay quiet:
//    truncating hides the date bug that made everybody eligible.
const threshold = Number(cfg.anomaly_threshold ?? 50);
if (n > threshold) reasons.push(`${n} candidates exceeds the anomaly threshold (${threshold})`);

// 2. The channel's real ceiling, read from the API (TIER_250).
if (gateA.messagingLimit && n > gateA.messagingLimit) {
  reasons.push(`${n} candidates exceeds the channel limit (${gateA.messagingLimit})`);
}

// 3. Balance. The cost is PER TEMPLATE: milestone 20 alternates between Utility and
//    Marketing, and the difference is almost 7x.
const pM = Number(cfg.price_marketing ?? 0.074);
const pU = Number(cfg.price_utility   ?? 0.0113);
const nM = base.candidates.filter(c => c.category === 'marketing').length;
const nU = n - nM;
const cost   = nM * pM + nU * pU;
const margin = Number(cfg.balance_margin ?? 2);

const balanceRaw = $('Balance').first().json ?? {};
const balance = Number(balanceRaw.balance ?? balanceRaw.amount ?? balanceRaw.available ?? NaN);
if (n > 0) {
  if (!Number.isFinite(balance)) {
    reasons.push(`Could not read the YCloud balance. Response: ${JSON.stringify(balanceRaw).slice(0, 200)}`);
  } else if (balance < cost * margin) {
    reasons.push(`Balance ${balance.toFixed(4)} is below the estimated cost ${cost.toFixed(4)} x margin ${margin}`);
  }
}

// 4. The table shrank (design D-E). This also covers restoring an old
//    backup, which is the INV-17 scenario.
const rows = Number($('Table Health').first().json.total ?? 0);
const mark = Number(cfg.sends_max_seen ?? 0);
if (rows < mark) {
  reasons.push(`bot.sends has ${rows} rows and the watermark is ${mark}: the table shrank`);
}

return [{ json: {
  ...base,
  gateOk: reasons.length === 0,
  reasons,
  estimatedCost: cost,
  balance: Number.isFinite(balance) ? balance : null,
  nMarketing: nM,
  nUtility: nU,
}}];

