parameters.jsCode:
// Only here is the envelope opened into one item per patient. Everything before
// ran a single time, so no node made N identical queries.
return $input.first().json.candidates.map(c => ({ json: c }));

// The summary ALWAYS goes out: with sends, with zero candidates, or on a Sunday.
// That is INV-13, and it is the half that was missing in July: six days of
// "successful" executions without a single signal that dozens of patients were receiving nothing.
const g = $('Gate B · Decide').first().json;

// Per-patient results only exist if there were sends. On the zero-candidates
// branch the input is the envelope itself, which carries no 'status'.
const results = $input.all().map(i => i.json).filter(r => r && r.status !== undefined);
const count = (s) => results.filter(r => r.status === s).length;

const d = g.discards ?? {};
// Out by branch is a decision, not data to fix (spec 4.1, D15). If it were added
// to the discards, the total would be a big, fixed number that nobody reads.
const BY_BRANCH = ['satellite', 'other_branch'];
const totalDiscards = Object.entries(d)
  .filter(([k]) => !BY_BRANCH.includes(k))
  .reduce((a, [, v]) => a + v, 0);
const outByBranch = BY_BRANCH.reduce((a, k) => a + (d[k] ?? 0), 0);
const when = DateTime.now().setZone('America/Costa_Rica').toFormat('dd/MM/yyyy HH:mm');

let text = `FOLLOWUP SUMMARY - ${when}\n\n`;

if (g.isSunday) {
  text += 'Sunday: nothing is sent (spec 4.4). The bot ran anyway to leave a signal.\n\n';
}

text += `Patients read: ${g.totalPatients}\n`;
text += `Today's candidates: ${g.candidates.length}\n`;
if (g.alreadyContacted) text += `Already contacted before, skipped: ${g.alreadyContacted}\n`;
if (g.optOutsApplied)   text += `Marketing opt-outs applied (opt2 -> opt1): ${g.optOutsApplied}\n`;

if (results.length) {
  text += `\nSent: ${count('sent')}\n`;
  text += `Failed: ${count('failed')}\n`;
  text += `Ambiguous: ${count('ambiguous')}\n`;
  const preex = count('preexisting');
  if (preex) text += `Key already existed, nothing sent: ${preex}\n`;
} else if (!g.isSunday) {
  text += '\nNothing was sent today.\n';
}

if (outByBranch) {
  text += `\nOut by branch (a decision, no action needed): ${outByBranch}\n`;
  if (d.satellite)      text += `  SATELLITE: ${d.satellite}\n`;
  if (d.other_branch)   text += `  without the MAIN branch: ${d.other_branch}\n`;
}

// INV-12: discards are visible. That is what lets the staff fix dates and
// phones in the app, instead of them getting lost in silence.
if (totalDiscards) {
  text += `\nDiscarded: ${totalDiscards}\n`;
  if (d.no_branch)      text += `  no branch: ${d.no_branch}\n`;
  if (d.no_date)        text += `  no plan date: ${d.no_date}\n`;
  if (d.invalid_date)   text += `  unreadable date: ${d.invalid_date}\n`;
  if (d.no_phone)       text += `  NO PHONE and due today: ${d.no_phone}\n`;
  if (d.odd_phone)      text += `  phone that does not fit E.164: ${d.odd_phone}\n`;
}
if (g.discardDetails?.length) {
  text += `\nTo fix in the app:\n${g.discardDetails.join('\n')}\n`;
}

text += `\nEstimated cost: ${Number(g.estimatedCost ?? 0).toFixed(4)} USD`;

// Telegram cuts at 4096 characters.
if (text.length > 3800) text = text.slice(0, 3800) + '\n... (truncated)';

return [{ json: { text, sent: count('sent'), failed: count('failed'), ambiguous: count('ambiguous') } }];

parameters.query:
update bot.config
   set value = greatest(value::bigint, (select count(*) from bot.sends))::text
 where name = 'sends_max_seen';
